class Solution {
public:
    int nthMagicalNumber(int n, int a, int b) {
        const long long MOD = 1000000007LL;
        long long L = lcmLL(a, b);
        long long k = L / a + L / b - 1;
        long long full = (long long)(n - 1) / k;
        long long rem  = (long long)(n - 1) % k + 1;
        long long lo = 1, hi = L;
        while (lo < hi) {
            long long mid = lo + (hi - lo) / 2;
            long long cnt = mid / a + mid / b - mid / L;
            if (cnt >= rem) hi = mid;
            else            lo = mid + 1;
        }
        long long ans = (full % MOD) * (L % MOD) % MOD + (lo % MOD);
        return (int)(ans % MOD);
    }
private:
    long long gcdLL(long long x, long long y) {
        while (y) { long long t = x % y; x = y; y = t; }
        return x;
    }
    long long lcmLL(long long x, long long y) {
        return x / gcdLL(x, y) * y;
    }
};
